public class InnerRouterInputRouterInputProtocolConfigurationFactory(Action<Humidifier.MediaConnect.RouterInputTypes.RouterInputProtocolConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MediaConnect.RouterInputTypes.RouterInputProtocolConfiguration>
{

    internal InnerRouterInputSrtCallerRouterInputConfigurationFactory SrtCallerFactory { get; set; }

    internal InnerRouterInputSrtListenerRouterInputConfigurationFactory SrtListenerFactory { get; set; }

    internal InnerRouterInputRistRouterInputConfigurationFactory RistFactory { get; set; }

    internal InnerRouterInputRtpRouterInputConfigurationFactory RtpFactory { get; set; }

    protected override Humidifier.MediaConnect.RouterInputTypes.RouterInputProtocolConfiguration Create()
    {
        var routerInputProtocolConfigurationResult = CreateRouterInputProtocolConfiguration();
        factoryAction?.Invoke(routerInputProtocolConfigurationResult);

        return routerInputProtocolConfigurationResult;
    }

    private Humidifier.MediaConnect.RouterInputTypes.RouterInputProtocolConfiguration CreateRouterInputProtocolConfiguration()
    {
        var routerInputProtocolConfigurationResult = new Humidifier.MediaConnect.RouterInputTypes.RouterInputProtocolConfiguration();

        return routerInputProtocolConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaConnect.RouterInputTypes.RouterInputProtocolConfiguration result)
    {
        base.CreateChildren(result);

        result.SrtCaller ??= SrtCallerFactory?.Build();
        result.SrtListener ??= SrtListenerFactory?.Build();
        result.Rist ??= RistFactory?.Build();
        result.Rtp ??= RtpFactory?.Build();
    }

} // End Of Class

